                    setChromeHidden(false);
                    var idx = config.chapters.findIndex(function (c) { return c.id === id; });
                    var chapter = config.chapters[idx];
                    if (!chapter) return;
                    navItems.forEach(function (it) { it.classList.toggle('active', it.getAttribute('data-id') === id); });
